from typing import List

class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
        best = nums[0]
        for left in range(len(nums)):
            current = 0
            for right in range(left, len(nums)):
                current += nums[right]
                best = max(best, current)
        return best

